import{_ as r,a0 as s,w as p,s as u,ao as e,I as i,a1 as a,A as l,x as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"圖解 Rocky Linux 9 安裝步驟 | LCTT x X-CMD","titleTemplate":false,"description":"圖解 Rocky Linux 9 安裝步驟 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"圖解 Rocky Linux 9 安裝步驟 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"圖解 Rocky Linux 9 安裝步驟 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20220718 How to Install Rocky Linux 9 Step by Step with Screenshots","title":"圖解 Rocky Linux 9 安裝步驟","tag":"202208","desc":""},"relativePath":"202208/20220718 How to Install Rocky Linux 9 Step by Step with Screenshots.md","filePath":"[post].md"}'),c={name:"202208/20220718 How to Install Rocky Linux 9 Step by Step with Screenshots.md"};function y(h,t,d,x,k,b){const o=s("Link");return p(),u("div",null,[t[17]||(t[17]=e('<h1 id="圖解-rocky-linux-9-安裝步驟" tabindex="-1">圖解 Rocky Linux 9 安裝步驟 <a class="header-anchor" href="#圖解-rocky-linux-9-安裝步驟" aria-label="Permalink to “圖解 Rocky Linux 9 安裝步驟”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202208/08/172822s7zwhj7wuzzjfm25.jpg" alt=""></p><blockquote><p>這篇教程中，我們將圖解 Rocky Linux 9 安裝步驟。</p></blockquote><p><ruby>Rocky 企業軟件基金會<rt>Rocky Enterprise Software Foundation</rt></ruby> 已經發布了它的最新的操作系統 “Rocky Linux 9”。Rocky Linux 是針對工作站和服務器的自由而開源的操作系統。它被認為是 CentOS Linux 的繼承者。</p><p>Rocky Linux 9 是 RHEL 9 的複製品，其開發代號是“Blue Onyx”。Rocky Linux 和 RHEL 之間的主要不同是，它有它自己的名為 “Peridot” 的開源構建系統。</p><h3 id="rocky-linux-9-的更新和特色" tabindex="-1">Rocky Linux 9 的更新和特色 <a class="header-anchor" href="#rocky-linux-9-的更新和特色" aria-label="Permalink to “Rocky Linux 9 的更新和特色”">​</a></h3><ul><li>Gnome 40 是默認的桌面環境</li><li>在 XFS 文件系統上支持<ruby>直接訪問<rt>Direct Access</rt></ruby>（DAX）操作</li><li>更新了運行時和編譯器，如 GCC 11.2.1 、LLVM 13.0.1 、Rust 1.58.1 和 Go 1.17.1</li><li>更新了開發工具鏈，如 Python 3.9 、Node.js 16 、Ruby 3.0.3 、Perl 5.32 和 PHP 8.0</li><li>ssh 默認禁用了 root 用户身份驗證</li><li>更新了 OpenSSL 3.0，改進了 Cockpit 網頁主控台</li><li>社區提供支持到 2032 年 05 月 31 日</li></ul><h3 id="前置條件" tabindex="-1">前置條件 <a class="header-anchor" href="#前置條件" aria-label="Permalink to “前置條件”">​</a></h3><ul><li>2 GB 及更多的內存</li><li>2 個 CPU 核心（1.1 GHz 及更高)</li><li>20 GB 硬盤空間</li><li>可啓動介質（USD 或 DVD）</li><li>互聯網連接（可選）</li></ul><p>不再耽誤時間，讓我們直接進入 Rocky Linux 9 的安裝步驟：</p><h3 id="_1、下載-rocky-linux-9-的-iso-文件" tabindex="-1">1、下載 Rocky Linux 9 的 ISO 文件 <a class="header-anchor" href="#_1、下載-rocky-linux-9-的-iso-文件" aria-label="Permalink to “1、下載 Rocky Linux 9 的 ISO 文件”">​</a></h3><p>使用下面的官方網址來下載 ISO 文件</p>',12)),i("blockquote",null,[i("p",null,[i("strong",null,[a(o,{href:"https://rockylinux.org/download"},{default:l(()=>[...t[0]||(t[0]=[n("Rocky Linux 9 ISO",-1)])]),_:1})])])]),t[18]||(t[18]=i("p",null,"在你下載 ISO 文件後，使用已下載的 ISO 文件製作一個可啓動介質（USB/DVD）。",-1)),t[19]||(t[19]=i("p",null,"在 Windows 中，你可以利用 Rufus 軟件來使用 ISO 文件來製作可啓動 USB 驅動器。在 Linux 中，參考下面的內容：",-1)),i("blockquote",null,[i("p",null,[i("strong",null,[a(o,{href:"https://www.linuxtechi.com/create-bootable-usb-disk-dvd-ubuntu-linux-mint/"},{default:l(()=>[...t[1]||(t[1]=[n("在 Ubuntu / Linux Mint 上，如何創建可啓動 USB 驅動器",-1)])]),_:1})])])]),t[20]||(t[20]=e(`<h3 id="_2、使用可啓動媒介盤啓動系統" tabindex="-1">2、使用可啓動媒介盤啓動系統 <a class="header-anchor" href="#_2、使用可啓動媒介盤啓動系統" aria-label="Permalink to “2、使用可啓動媒介盤啓動系統”">​</a></h3><p>在你計劃安裝 Rocky Linux 9 的硬件系統上，BIOS 設置中將可啓動介質從硬盤驅動器更改為 USB 驅動器, 重新啓動它。</p><p>在硬件系統使用可啓動介質啓動後，我們將看到下面的屏幕，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Select-Install-Rocky-Linux-9-option.png" alt="Select-Install-Rocky-Linux-9-option"></p><p>選擇第一個選項， <ruby>安裝 Rocky Linux 9.0<rt>Install Rocky Linux 9.0</rt></ruby> ，並按下 <ruby>回車<rt>enter</rt></ruby> 按鍵。</p><h3 id="_3、選擇首選語言" tabindex="-1">3、選擇首選語言 <a class="header-anchor" href="#_3、選擇首選語言" aria-label="Permalink to “3、選擇首選語言”">​</a></h3><p>選擇<strong>安裝過程</strong>的首選語言，然後單擊 <ruby>繼續<rt>Continue</rt></ruby> 按鈕，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Preferred-Language-for-RockyLinux9-Installation.png" alt="Preferred-Language-for-RockyLinux9-Installation"></p><h3 id="_4、安裝過程摘要" tabindex="-1">4、安裝過程摘要 <a class="header-anchor" href="#_4、安裝過程摘要" aria-label="Permalink to “4、安裝過程摘要”">​</a></h3><p>在這個步驟中，我們將看到如下的初始安裝摘要。要開始安裝，首先，我們必須完成標記項目，如 <ruby>安裝目標<rt>Installation Destination</rt></ruby> 和 <ruby>用户設置<rt>User settings</rt></ruby>。</p><p>除了已標記的項目外，我們也可以更改現有的項目，只需要按照你的要求單擊它們就可以進行更改。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Initial-Installation-Summary-Rocky-Linux9.png" alt="Initial-Installation-Summary-Rocky-Linux9"></p><h4 id="配置安裝目標" tabindex="-1">配置安裝目標 <a class="header-anchor" href="#配置安裝目標" aria-label="Permalink to “配置安裝目標”">​</a></h4><p>在這個項目中，我們將為 Rocky Linux 具體指定分區方案。單擊 <ruby>安裝目標<rt>Installation Destination</rt></ruby>。</p><p>在這裏，我們可以為 <ruby>存儲配置<rt>storage configuration</rt></ruby> 或 <ruby>分區方案<rt>partition scheme</rt></ruby> 選擇 <ruby>自動<rt>automatic</rt></ruby> 選項或 <ruby>自定義<rt>custom </rt></ruby> 選項。</p><p>在自動選項中，安裝程序將在磁盤上自動地創建分區，而自定義選項允許我們在磁盤上手動創建分區。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Choose-custom-Storage-Configuration-Rocky-Linux9.png" alt="Choose-custom-Storage-Configuration-Rocky-Linux9"></p><p>在這篇指南中，我將使用 <ruby>自定義<rt>Custom</rt></ruby> 選項，單擊 <ruby>執行<rt>Done</rt></ruby> 按鈕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Standard-Partition-Scheme-RockyLinux9.png" alt="Standard-Partition-Scheme-RockyLinux9"></p><p>在該 40 GB 的磁盤上，我們將創建以下分區，</p><ul><li><code>/boot</code>：2GB（xfs 文件系統）</li><li><code>/</code>：10 GB（xfs 文件系統）</li><li><code>/home</code>：25 GB（xfs 文件系統）</li><li>交換分區：2 GB</li></ul><p>開始創建分區，選擇 <ruby>標準分區<rt>Standard Partition</rt></ruby> 方案，然後單擊 “+” 符號。</p><p>創建第一個分區，大小為 2 GB 的 <code>/boot</code> 分區，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Boot-Partition-RockyLinux9-Installation.png" alt="Boot-Partition-RockyLinux9-Installation"></p><p>單擊 <ruby>添加掛載點<rt>Add mount point</rt></ruby> 按鈕。</p><p>類似地，接下來分別創建大小為 10 GB 的 <code>/</code> 分區和 25 GB 的 <code>/home</code> 分區。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Slash-Partition-Rocky-Linux9-installation.png" alt="Slash-Partition-Rocky-Linux9-installation"></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Home-Partition-Rocky-Linux9-Installation.png" alt="Home-Partition-Rocky-Linux9-Installation"></p><p>現在，創建最後一個分區，大小為 2 GB 的交換分區，（LCTT 校注：如果你的內存非常多，你可以選擇不創建交換分區。另外，對於生產環境，建議將存儲數據的目錄單獨劃分分區。）</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Swap-Partition-RockyLinux9-Installation.png" alt="Swap-Partition-RockyLinux9-Installation"></p><p>在你完成手動分區後，單擊 <ruby>執行<rt>Done</rt></ruby> 按鈕來完成這個項目。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Finish-Manual-Partitioning-RockyLinux9-Installation.png" alt="Finish-Manual-Partitioning-RockyLinux9-Installation"></p><p>選擇 <ruby>接受更改<rt>Accept Changes</rt></ruby> 按鈕來將這些更改寫入磁盤。它也將返回到安裝摘要屏幕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Accept-Changes-to-Write-on-Disk-RockyLinux9.png" alt="Accept-Changes-to-Write-on-Disk-RockyLinux9"></p><h4 id="配置用户設置" tabindex="-1">配置用户設置 <a class="header-anchor" href="#配置用户設置" aria-label="Permalink to “配置用户設置”">​</a></h4><p>在 <ruby>用户設置<rt>User Settings</rt></ruby> 下，單擊 <ruby>root 密碼 <rt>Root Password</rt></ruby> 按鈕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Set-Root-Password-RockyLinux9-Instalation.png" alt="Set-Root-Password-RockyLinux9-Instalation"></p><p>設置 root 用户的密碼，並單擊 <ruby>執行<rt>Done</rt></ruby> 按鈕。</p><p>再次回到 <ruby>用户設置<rt>User Settings</rt></ruby> 下，單擊 <ruby>用户創建<rt>User Creation</rt></ruby> 按鈕，具體指定本地用户的詳細信息，例如用户名稱和密碼。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Local-User-Create-During-RockyLinux9-Installation.png" alt="Local-User-Create-During-RockyLinux9-Installation"></p><p>單擊 <ruby>執行<rt>Done</rt></ruby> 按鈕，它也將返回到安裝摘要。</p><p>現在，我們準備開始安裝，單擊<ruby>開始安裝<rt>Begin Installation</rt></ruby> 按鈕，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Begin-Installation-Option-RockyLinux9.png" alt="Begin-Installation-Option-RockyLinux9"></p><h3 id="_5、安裝過程開始" tabindex="-1">5、安裝過程開始 <a class="header-anchor" href="#_5、安裝過程開始" aria-label="Permalink to “5、安裝過程開始”">​</a></h3><p>在這一步驟中，安裝程序已經開始了，並在正在進行中，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/RockyLinux9-Installation-Progress.png" alt="RockyLinux9-Installation-Progress"></p><p>在安裝過程完成後，安裝程序將提示你重新啓動系統。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Reboot-System-after-RockyLinux9-Installation.png" alt="Reboot-System-after-RockyLinux9-Installation"></p><p>單擊 <ruby>重新啓動系統<rt>Reboot System</rt></ruby> 按鈕。</p><p>注意：不要忘記在 BIOS 設置中將可啓動介質從 USB 啓動更改為硬盤驅動器啓動。</p><h3 id="_6、安裝後的登錄屏幕和桌面環境" tabindex="-1">6、安裝後的登錄屏幕和桌面環境 <a class="header-anchor" href="#_6、安裝後的登錄屏幕和桌面環境" aria-label="Permalink to “6、安裝後的登錄屏幕和桌面環境”">​</a></h3><p>在成功安裝後，當系統啓動時，我們將看到下面的登錄屏幕：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/RockyLinux9-Loginscreen-Post-Installation.png" alt="RockyLinux9-Loginscreen-Post-Installation"></p><p>使用我們在安裝期間創建的用户名稱和密碼，按下 <ruby>回車<rt>enter</rt></ruby> 按鍵來登錄。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Desktop-Env-RockyLinux9.png" alt="Desktop-Env-RockyLinux9"></p><p>打開終端，依次運行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install epel-release -y</span></span>
<span class="line"><span>$ sudo dnf install neofetch -y</span></span></code></pre></div><p>現在，來驗證系統的詳細信息，運行 <code>neofetch</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ neofetch</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/neofetch-rockylinux9-post-installation.png" alt="neofetch-rockylinux9-post-installation"></p><p>這就是這篇指南的全部內容，我希望它對你有用。請在下面的評論區貼出你的疑問和反饋。</p><hr>`,62)),i("p",null,[t[3]||(t[3]=n("via: ",-1)),a(o,{href:"https://www.linuxtechi.com/how-to-install-rocky-linux-9-step-by-step/"},{default:l(()=>[...t[2]||(t[2]=[n("https://www.linuxtechi.com/how-to-install-rocky-linux-9-step-by-step/",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=n("作者：",-1)),a(o,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:l(()=>[...t[4]||(t[4]=[n("Pradeep Kumar",-1)])]),_:1}),t[9]||(t[9]=n(" 選題：",-1)),a(o,{href:"https://github.com/lkxed"},{default:l(()=>[...t[5]||(t[5]=[n("lkxed",-1)])]),_:1}),t[10]||(t[10]=n(" 譯者：",-1)),a(o,{href:"https://github.com/robsean"},{default:l(()=>[...t[6]||(t[6]=[n("robsean",-1)])]),_:1}),t[11]||(t[11]=n(" 校對：",-1)),a(o,{href:"https://github.com/wxy"},{default:l(()=>[...t[7]||(t[7]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[14]||(t[14]=n("本文由 ",-1)),a(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[12]||(t[12]=[n("LCTT",-1)])]),_:1}),t[15]||(t[15]=n(" 原創編譯，",-1)),a(o,{href:"https://linux.cn/"},{default:l(()=>[...t[13]||(t[13]=[n("Linux中國",-1)])]),_:1}),t[16]||(t[16]=n(" 榮譽推出",-1))])])}const L=r(c,[["render",y]]);export{g as __pageData,L as default};
